pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    BankCaller caller;

    function setUp() public {
        c = new C();
        caller = new BankCaller(c);
    }

    function testFuzz_property(uint256 n) public {
        vm.assume(n >= 1 && n <= 10);
        caller.drop(n);
        assertTrue(c.tokenBalance(address(1)) == 0);
    }
}

interface IC {
    function airDrop() external;
    function tokenBalance(address) external view returns (uint256);
}

contract BankCaller {
    IC c;
    constructor(IC c_) { c = c_; }
    function drop(uint256 n) external {
        for (uint256 i = 0; i < n; i++) {
            c.airDrop();
        }
    }
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}

