pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address k) public {
        // airDrop() verifies keccak over its msg.sender via Bank(msg.sender).supportsToken(),
        // so the actor must be a contract; we deploy a fresh caller each run (the actor's
        // identity is derived, not a hard-coded deciding value).
        Caller caller = new Caller(address(c));

        caller.hit();

        // General rule: a successful airDrop credits exactly the caller's own mapping key
        // with 20 tokens and leaves every other key untouched.
        assertTrue(c.tokenBalance(k) == (k == address(caller) ? 20 : 0));
    }
}

contract Caller {
    C c;
    constructor(address target) { c = C(target); }
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
    function hit() external { c.airDrop(); }
}

