pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 salt) public {
        // The caller's address is determined by the fuzzed salt (CREATE2); any
        // Bank-compatible caller with zero balance is admissible.
        Caller caller = new Caller{salt: bytes32(salt)}(c);
        // The call must have succeeded (modifiers satisfied) and the caller
        // must have been credited 20 at ITS OWN key by the reference.
        assertTrue(caller.ok() && c.tokenBalance(address(caller)) == 20);
    }
}

contract Caller {
    C immutable target;
    bool public ok;
    constructor(C t) {
        target = t;
        // airDrop requires Bank(msg.sender).supportsToken() == hash("Nu Token")
        try t.airDrop() { ok = true; } catch { ok = false; }
    }
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}

