pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public {
        c = new C();
        attacker = new Attacker();
    }

    function testFuzz_property(uint256 seed) public {
        uint256 bump = bound(seed, 0, 3);
        // optional warm-up airdrops: after the first, the caller's balance is nonzero
        for (uint256 i = 0; i < bump; i++) {
            attacker.doAirdrop(c);
        }
        bool ok;
        try attacker.doAirdropTry(c) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: a Bank-impersonating caller always ends with exactly 20 tokens
        // after (at most one successful) airDrop; the mutant violates this for every bump.
        assertTrue(c.tokenBalance(address(attacker)) == 20, "balance must settle at 20");
    }
}

contract Attacker is Bank {
    function doAirdrop(C c) external {
        c.airDrop();
    }

    function doAirdropTry(C c) external {
        c.airDrop();
    }
}

