pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Caller a1;
    Caller a2;

    function setUp() public {
        c = new C();
        a1 = new Caller(c);
        a2 = new Caller(c);
    }

    function testFuzz_property(uint256 seed) public {
        vm.assume(seed < type(uint256).max);
        bool ok1;
        bool ok2;
        if (seed % 2 == 0) {
            try a1.callAirDrop() { ok1 = true; } catch { ok1 = false; }
            try a2.callAirDrop() { ok2 = true; } catch { ok2 = false; }
        } else {
            try a2.callAirDrop() { ok2 = true; } catch { ok2 = false; }
            try a1.callAirDrop() { ok1 = true; } catch { ok1 = false; }
        }
        assertTrue(ok1 && ok2 && c.tokenBalance(address(a1)) == 20 && c.tokenBalance(address(a2)) == 20);
    }
}

contract Caller is C.Bank {
    C target;
    constructor(C t) { target = t; }
    function callAirDrop() external { target.airDrop(); }
}

