import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(bool doReenter, uint256 filler) public {
        Attacker attacker = new Attacker(c, doReenter);
        attacker.go();
        // General rule: reentrancy protection guarantees each caller receives
        // exactly one airdrop grant, even a caller that re-enters mid-execution.
        assertTrue(c.tokenBalance(address(attacker)) == 20);
    }
