pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 rounds) public {
        rounds = bound(rounds, 1, 3); // any n>=1 triggers; domain kept wide enough to include the trigger
        Attacker a = new Attacker(c);
        a.setRounds(rounds);
        try a.attack() {
            // correct contract: re-entrant calls are blocked, exactly one 20-token grant lands
            assertTrue(c.tokenBalance(address(a)) == 20, "reentrancy guard must cap grant at 20");
        } catch {
            assertTrue(false, "outer airDrop must not revert on the correct contract");
        }
    }
}

contract Attacker {
    C public c;
    uint256 public rounds;
    bool private inside;

    constructor(C _c) { c = _c; }

    function setRounds(uint256 n) external { rounds = n; }

    function attack() external {
        c.airDrop();
    }

    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }

    // hook invoked by c's supportsToken modifier; re-enter airDrop while the outer call is mid-flight
    fallback() external {
        if (!inside) {
            inside = true;
            for (uint256 i = 0; i < rounds; i++) {
                (bool ok,) = address(c).call(abi.encodeWithSignature("airDrop()"));
                ok; // ignore revert (reference blocks re-entry)
            }
            inside = false;
        }
    }
}

