pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 reenterSeed) public {
        uint256 depth = bound(reenterSeed, 1, 3);
        Attacker attacker = new Attacker(c);
        attacker.setTarget(depth);
        vm.prank(address(attacker));
        c.airDrop();
        // Invariant: any completed airDrop grants exactly 20 tokens, regardless
        // of how many re-entrant attempts the token-verification counterparty makes.
        assertTrue(c.tokenBalance(address(attacker)) == 20, "balance must be exactly 20");
    }
}

contract Attacker {
    C public c;
    uint256 public depth;
    uint256 public target;

    constructor(C _c) { c = _c; }

    function setTarget(uint256 t) external { target = t; }

    function supportsToken() external returns (bytes32) {
        if (depth < target) {
            depth++;
            try c.airDrop() {} catch {}
        }
        return keccak256(abi.encodePacked("Nu Token"));
    }
}
